def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            objs.append(cells)
    target = min(objs, key=lambda cells: min(r for r, c in cells))
    for r, c in target:
        out[r][c] = 0
    return out
